      "topic": "Week 3 · Unit 2 Tutorial + Unit 3 Demand & Supply 需求与供给",
      "q": "Coffee and tea are substitutes. Tea becomes more expensive while coffee production costs fall. Predict the change in the equilibrium quantity and price of coffee.",
      "answer": "Coffee demand rises as some consumers switch from tea. Coffee supply also rises because costs fall. Both shifts raise quantity. Price is ambiguous because demand puts upward pressure on it and supply puts downward pressure on it.",
      "kind": "Economic analysis",
      "minutes": 3,
      "href": "#/c/economics/term1/3"
