      "week": 3,
      "topic": "Week 3 · Unit 2 Tutorial + Unit 3 Demand & Supply 需求与供给",
      "q": "A per-unit tax is imposed on sellers. Demand is less elastic than supply. Who generally bears more of the tax and why?",
      "answer": "Buyers generally bear more. They adjust quantity demanded less readily than sellers adjust quantity supplied, so the buyer price typically rises by more than the net seller price falls.",
