      "q": "An exact XLOOKUP fails for a code pasted with an ordinary trailing space. The reference codes are clean. Fix the lookup.",
      "answer": "Wrap the lookup value in TRIM, for example =XLOOKUP(TRIM(B2),Products!$A$2:$A$31,Products!$B$2:$B$31,\"Unknown\"). Check that a genuinely absent code still returns Unknown.",
