      "q": "Identify duplicate order numbers in A2:A101 without deleting rows.",
      "answer": "Enter =IF(A2=\"\",\"\",IF(COUNTIF($A$2:$A$101,A2)>1,\"Duplicate\",\"\")) and fill down. Both copies of a repeated number should be flagged.",
