      "topic": "高级 Excel：嵌套函数与 IF/AND、IF/OR",
      "q": "A pass requires a score of at least 50 in B2 and attendance of at least 80% in C2. Write the result formula.",
      "answer": "=IF(AND(B2>=50,C2>=80%),\"Pass\",\"Fail\"). Test 50 and 80% together to confirm both boundaries are inclusive.",
