      "week": 1,
      "topic": "高级 Excel：嵌套函数与 IF/AND、IF/OR",
      "q": "Approve shipping if B2 says Member or C2 is at least 100. Otherwise return Standard.",
      "answer": "=IF(OR(B2=\"Member\",C2>=100),\"Approved\",\"Standard\"). Either condition alone is sufficient.",
      "kind": "Excel logical formulas",
