      "q": "Assign High for scores of at least 80, Medium for 60–79 and Low below 60.",
      "answer": "=IF(B2>=80,\"High\",IF(B2>=60,\"Medium\",\"Low\")). Check the highest threshold first so the lower branch does not capture it.",
      "kind": "Excel logical formulas",
      "minutes": 3,
