      "topic": "高级 Excel：嵌套函数与 IF/AND、IF/OR",
      "q": "A score of 92 is incorrectly classified as Medium by =IF(B2>=60,\"Medium\",IF(B2>=80,\"High\",\"Low\")). Correct it.",
      "answer": "=IF(B2>=80,\"High\",IF(B2>=60,\"Medium\",\"Low\")). At 92 the first true condition returns High immediately.",
