      "topic": "高级 Excel：嵌套函数与 IF/AND、IF/OR",
      "q": "Flag a row when either the order date in B2 or the amount in C2 is empty.",
      "answer": "=IF(OR(B2=\"\",C2=\"\"),\"Incomplete\",\"Ready\"). The row is incomplete even if just one field is blank.",
