      "q": "Return blank for an empty score, Invalid for scores outside 0–100, and OK otherwise. Assume entered scores are numeric.",
      "answer": "=IF(B2=\"\",\"\",IF(OR(B2<0,B2>100),\"Invalid\",\"OK\")). The initial test distinguishes blanks from numeric zero.",
